const filas = $input.all().map(item => item.json);
const porSede = {}; const porEspecialidad = {};
for (const fila of filas) { const sede = porSede[fila.locationName] ??= { total: 0, APPROVED: 0, COMPLETED: 0, NO_SHOW: 0, CANCELLED: 0 }; sede.total += Number(fila.total); if (sede[fila.status] !== undefined) sede[fila.status] += Number(fila.total); porEspecialidad[fila.specialtyName] = (porEspecialidad[fila.specialtyName] ?? 0) + Number(fila.total); }
const resumenSedes = Object.entries(porSede).map(([nombre, datos]) => `- ${nombre}: ${datos.total} total | Aprobadas: ${datos.APPROVED} | Completadas: ${datos.COMPLETED} | No asistió: ${datos.NO_SHOW} | Canceladas: ${datos.CANCELLED}`).join('\n') || '- Sin citas para la fecha.';
const resumenEspecialidades = Object.entries(porEspecialidad).map(([nombre, total]) => `- ${nombre}: ${total}`).join('\n') || '- Sin especialidades con citas.';
return [{ json: { fecha: $now.toFormat('yyyy-LL-dd'), totalCitas: filas.reduce((s, fila) => s + Number(fila.total), 0), resumenSedes, resumenEspecialidades, incidenciasApi: 'Sin incidencias de API.' } }];

